function ActivityTurnOverCardsTaskPopupCell:FreshBaseUI(data)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting2836, "FlipCardTaskVo", data.id)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    if scr then
        scr:FreshBaseUI({{goodsId = vo.reward, goodsNum = vo.rewardNum}})
    end
    CfUtils.FillText(self.TextDescribe, vo.desc)
    CfUtils.FillText(self.TextProgress, string.format("<size=30><color=#545454>%s</color></size>/%s", data.progress, vo.taskContenNum))
    self.ProgressBar.value = checkNumber(data.progress) / checkNumber(vo.taskContenNum)
    local canGet = checkNumber(data.status) == Constants.GetStatus.Can

    CfUtils.SetUISwitchImage(self.ImgProgress, canGet and SwitchImageStatus.Can or SwitchImageStatus.Other)
    CfUtils.SetUISwitchImage(self.ImgCanFrame1, canGet and SwitchImageStatus.Can or SwitchImageStatus.Other)
    CfUtils.SetUISwitchImage(self.ImgCanFrame2, canGet and SwitchImageStatus.Can or SwitchImageStatus.Other)
    local hasGet = checkNumber(data.status) == Constants.GetStatus.Has
    local isAchieve = checkNumber(data.progress) >= checkNumber(vo.taskContenNum)
    local canJump = checkNumber(vo.openType) > 0
    KTool.SetActive(self.Underway, (not isAchieve) and (not canJump))
    if (not isGet) and canGet then
        self.BtnDrawReward.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B12", localize("领取"))
    elseif canJump and (not isGet) and (not canGet) then
        self.BtnDrawReward.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B13", localize("前往"))
    end
    UIEventProxy.Create(self.BtnDrawReward.gameObject).onPointerClick = function(event)
        if canJump and (not hasGet) and (not canGet) then--跳转
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            local row = goodsConfMgr:GetJumpModuleRow(vo.openType)
            goodsConfMgr:ExecuteJump(row, {})
        elseif (not hasGet) and canGet then--领取
            if type(self.btnAction) == 'function' then
                self.btnAction()
            end
        end
    end
    KTool.SetActive(self.BtnDrawReward, (not hasGet) and (canGet or canJump))
    KTool.SetActive(self.FinishGroup, hasGet)
    KTool.SetActive(self.UIFX_ActivityCompletion, canGet)
end

function ActivityTurnOverCardsTaskPopupCell:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return ActivityTurnOverCardsTaskPopupCell